import express from 'express';

function formatTodo(row) {
  return {
    id: row.id,
    title: row.title,
    done: row.done === 1,
    createdAt: row.createdAt,
    updatedAt: row.updatedAt,
  };
}

const reNumeric = /^\d+$/;

function validateId(req, res, next) {
  if (!reNumeric.test(req.params.id)) {
    return res.status(400).json({ error: 'id must be a number' });
  }
  next();
}

function validateTitle(title, res) {
  if (title === undefined || title === null || typeof title !== 'string' || title.trim() === '') {
    res.status(400).json({ error: 'title is required' });
    return false;
  }
  if (title.length > 200) {
    res.status(400).json({ error: 'title must be 200 characters or less' });
    return false;
  }
  return true;
}

function validateDone(done, res) {
  if (done !== undefined && typeof done !== 'boolean') {
    res.status(400).json({ error: 'done must be a boolean' });
    return false;
  }
  return true;
}

export function createApp(db) {
  const app = express();

  app.use(express.json());

  // POST /todos
  app.post('/todos', (req, res) => {
    const body = req.body ?? {};
    const { title, done } = body;

    if (!validateTitle(title, res)) return;
    if (!validateDone(done, res)) return;

    const now = new Date().toISOString();
    const stmt = db.prepare(
      'INSERT INTO todos (title, done, createdAt, updatedAt) VALUES (?, ?, ?, ?)'
    );
    const result = stmt.run(title.trim(), done ? 1 : 0, now, now);
    const todo = db.prepare('SELECT * FROM todos WHERE id = ?').get(result.lastInsertRowid);
    res.status(201).json(formatTodo(todo));
  });

  // GET /todos
  app.get('/todos', (req, res) => {
    const { done } = req.query;
    let rows;
    if (done === 'true') {
      rows = db.prepare('SELECT * FROM todos WHERE done = 1').all();
    } else if (done === 'false') {
      rows = db.prepare('SELECT * FROM todos WHERE done = 0').all();
    } else {
      rows = db.prepare('SELECT * FROM todos').all();
    }
    res.json(rows.map(formatTodo));
  });

  // GET /todos/:id
  app.get('/todos/:id', validateId, (req, res) => {
    const todo = db.prepare('SELECT * FROM todos WHERE id = ?').get(Number(req.params.id));
    if (!todo) return res.status(404).json({ error: 'Todo not found' });
    res.json(formatTodo(todo));
  });

  // PUT /todos/:id
  app.put('/todos/:id', validateId, (req, res) => {
    const id = Number(req.params.id);
    const existing = db.prepare('SELECT * FROM todos WHERE id = ?').get(id);
    if (!existing) return res.status(404).json({ error: 'Todo not found' });

    const body = req.body ?? {};
    const { title, done } = body;

    if (title !== undefined && !validateTitle(title, res)) return;
    if (!validateDone(done, res)) return;

    const newTitle = title !== undefined ? title.trim() : existing.title;
    const newDone = done !== undefined ? (done ? 1 : 0) : existing.done;
    const now = new Date().toISOString();

    db.prepare('UPDATE todos SET title = ?, done = ?, updatedAt = ? WHERE id = ?')
      .run(newTitle, newDone, now, id);

    const updated = db.prepare('SELECT * FROM todos WHERE id = ?').get(id);
    res.json(formatTodo(updated));
  });

  // DELETE /todos/:id
  app.delete('/todos/:id', validateId, (req, res) => {
    const id = Number(req.params.id);
    const existing = db.prepare('SELECT * FROM todos WHERE id = ?').get(id);
    if (!existing) return res.status(404).json({ error: 'Todo not found' });
    db.prepare('DELETE FROM todos WHERE id = ?').run(id);
    res.status(204).send();
  });

  // Malformed JSON
  app.use((err, req, res, next) => {
    if (err.type === 'entity.parse.failed') {
      return res.status(400).json({ error: 'Invalid JSON' });
    }
    next(err);
  });

  return app;
}

