import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import request from 'supertest';
import { createDb } from '../src/db.js';
import { createApp } from '../src/app.js';

let db;
let app;

beforeEach(() => {
  db = createDb(':memory:');
  app = createApp(db);
});

afterEach(() => {
  db.close();
});

// ─── POST /todos ──────────────────────────────────────────────────────────────

describe('POST /todos', () => {
  it('creates a todo and returns 201 with full shape', async () => {
    const res = await request(app).post('/todos').send({ title: 'Buy milk' });
    expect(res.status).toBe(201);
    expect(res.body).toMatchObject({ title: 'Buy milk', done: false });
    expect(typeof res.body.id).toBe('number');
    expect(typeof res.body.createdAt).toBe('string');
    expect(typeof res.body.updatedAt).toBe('string');
  });

  it('accepts done: true', async () => {
    const res = await request(app).post('/todos').send({ title: 'Already done', done: true });
    expect(res.status).toBe(201);
    expect(res.body.done).toBe(true);
  });

  it('returns 400 when title is missing', async () => {
    const res = await request(app).post('/todos').send({});
    expect(res.status).toBe(400);
    expect(res.body.error).toBe('title is required');
  });

  it('returns 400 when title is empty string', async () => {
    const res = await request(app).post('/todos').send({ title: '' });
    expect(res.status).toBe(400);
    expect(res.body.error).toBe('title is required');
  });

  it('returns 400 when title is whitespace only', async () => {
    const res = await request(app).post('/todos').send({ title: '   ' });
    expect(res.status).toBe(400);
    expect(res.body.error).toBe('title is required');
  });

  it('returns 400 when title exceeds 200 characters', async () => {
    const res = await request(app).post('/todos').send({ title: 'a'.repeat(201) });
    expect(res.status).toBe(400);
  });

  it('returns 400 when done is not boolean', async () => {
    const res = await request(app).post('/todos').send({ title: 'Test', done: 'yes' });
    expect(res.status).toBe(400);
    expect(res.body.error).toBe('done must be a boolean');
  });

  it('returns 400 for malformed JSON body', async () => {
    const res = await request(app)
      .post('/todos')
      .set('Content-Type', 'application/json')
      .send('{invalid json}');
    expect(res.status).toBe(400);
  });
});

// ─── GET /todos ───────────────────────────────────────────────────────────────

describe('GET /todos', () => {
  it('returns empty array when no todos exist', async () => {
    const res = await request(app).get('/todos');
    expect(res.status).toBe(200);
    expect(res.body).toEqual([]);
  });

  it('lists all todos', async () => {
    await request(app).post('/todos').send({ title: 'Task 1' });
    await request(app).post('/todos').send({ title: 'Task 2', done: true });
    const res = await request(app).get('/todos');
    expect(res.status).toBe(200);
    expect(res.body).toHaveLength(2);
  });

  it('filters by done=true', async () => {
    await request(app).post('/todos').send({ title: 'Task 1' });
    await request(app).post('/todos').send({ title: 'Task 2', done: true });
    const res = await request(app).get('/todos?done=true');
    expect(res.status).toBe(200);
    expect(res.body).toHaveLength(1);
    expect(res.body[0].done).toBe(true);
  });

  it('filters by done=false', async () => {
    await request(app).post('/todos').send({ title: 'Task 1' });
    await request(app).post('/todos').send({ title: 'Task 2', done: true });
    const res = await request(app).get('/todos?done=false');
    expect(res.status).toBe(200);
    expect(res.body).toHaveLength(1);
    expect(res.body[0].done).toBe(false);
  });
});

// ─── GET /todos/:id ───────────────────────────────────────────────────────────

describe('GET /todos/:id', () => {
  it('returns a todo by id', async () => {
    const created = await request(app).post('/todos').send({ title: 'Find me' });
    const res = await request(app).get(`/todos/${created.body.id}`);
    expect(res.status).toBe(200);
    expect(res.body.title).toBe('Find me');
  });

  it('returns 404 for non-existent id', async () => {
    const res = await request(app).get('/todos/9999');
    expect(res.status).toBe(404);
    expect(res.body.error).toBeTruthy();
  });

  it('returns 400 for non-numeric id', async () => {
    const res = await request(app).get('/todos/abc');
    expect(res.status).toBe(400);
  });
});

// ─── PUT /todos/:id ───────────────────────────────────────────────────────────

describe('PUT /todos/:id', () => {
  it('updates title and done', async () => {
    const created = await request(app).post('/todos').send({ title: 'Original' });
    const res = await request(app)
      .put(`/todos/${created.body.id}`)
      .send({ title: 'Updated', done: true });
    expect(res.status).toBe(200);
    expect(res.body.title).toBe('Updated');
    expect(res.body.done).toBe(true);
  });

  it('partial update — only title', async () => {
    const created = await request(app).post('/todos').send({ title: 'Old', done: true });
    const res = await request(app)
      .put(`/todos/${created.body.id}`)
      .send({ title: 'New' });
    expect(res.status).toBe(200);
    expect(res.body.title).toBe('New');
    expect(res.body.done).toBe(true);
  });

  it('returns 404 for non-existent id', async () => {
    const res = await request(app).put('/todos/9999').send({ title: 'Nope' });
    expect(res.status).toBe(404);
  });

  it('returns 400 for non-numeric id', async () => {
    const res = await request(app).put('/todos/abc').send({ title: 'Test' });
    expect(res.status).toBe(400);
  });

  it('returns 400 when done is not boolean on update', async () => {
    const created = await request(app).post('/todos').send({ title: 'Test' });
    const res = await request(app)
      .put(`/todos/${created.body.id}`)
      .send({ done: 'nope' });
    expect(res.status).toBe(400);
    expect(res.body.error).toBe('done must be a boolean');
  });
});

// ─── DELETE /todos/:id ────────────────────────────────────────────────────────

describe('DELETE /todos/:id', () => {
  it('deletes a todo and returns 204', async () => {
    const created = await request(app).post('/todos').send({ title: 'Delete me' });
    const del = await request(app).delete(`/todos/${created.body.id}`);
    expect(del.status).toBe(204);
    const check = await request(app).get(`/todos/${created.body.id}`);
    expect(check.status).toBe(404);
  });

  it('returns 404 for non-existent id', async () => {
    const res = await request(app).delete('/todos/9999');
    expect(res.status).toBe(404);
  });

  it('returns 400 for non-numeric id', async () => {
    const res = await request(app).delete('/todos/abc');
    expect(res.status).toBe(400);
  });
});

